#!/usr/bin/env node

/**
 * Add Implementation References to Agent Specs
 *
 * Maps existing .agent.md files to their implementation directories
 * and adds the implementation field to spec frontmatter.
 */

import fs from "fs";
import path from "path";
import url from "url";
import * as YAML from "js-yaml";

const __dirname = path.dirname(url.fileURLToPath(import.meta.url));
const AGENTS_DIR = path.join(__dirname, "../../agents");

// Mapping of spec file names to implementation directory names
// Generated by matching existing directories in agents folder
const IMPLEMENTATION_MAPPING = {
  // Direct matches with existing directories
  adr: "adr-generator",
  linting: "linting-agent",
  meta: "meta-agent",
  "prompt-engineer": "prompt-engineer",
  release: "release",
  "task-planner": "task-planner-agent",
  "task-researcher": "task-researcher-agent",
  testing: "testing-agent",

  // Repository-internal agents (may not have implementation directories in agents/)
  // These are handled in .github/workflows or elsewhere
  issues: null, // Internal repository agent
  labeling: null, // Internal repository agent
  metrics: null, // Internal repository agent
  reporting: null, // Internal repository agent
  reviewer: null, // Internal repository agent

  // Mode agents - metadata agents
  "mode-demonstrate-understanding": null, // Mode specification only
  "mode-document-reviewer": null, // Mode specification only
  "mode-prd": null, // Mode specification only
  "mode-thinking": null, // Mode specification only

  // Utility agents
  "project-meta-sync": null, // Utility agent
  template: null, // Utility agent
};

/**
 * Parse frontmatter from markdown content
 */
function parseFrontmatter(content) {
  const match = content.match(/^---\n([\s\S]*?)\n---/);
  if (!match) return { yaml: null, content: content };

  try {
    const yaml = YAML.load(match[1]);
    const remaining = content.substring(match[0].length);
    return { yaml, remaining };
  } catch (e) {
    console.error(`Error parsing YAML: ${e.message}`);
    return { yaml: null, content: content };
  }
}

/**
 * Reconstruct markdown with updated frontmatter
 */
function reconstructMarkdown(frontmatter, content) {
  const yamlStr = YAML.dump(frontmatter, { indent: 2 });
  return `---\n${yamlStr}---\n${content}`;
}

/**
 * Check if implementation directory exists
 */
function directoryExists(dir) {
  try {
    return fs.statSync(dir).isDirectory();
  } catch {
    return false;
  }
}

/**
 * Update spec file with implementation reference
 */
function updateSpecFile(specName, specPath, implementationDir) {
  const content = fs.readFileSync(specPath, "utf8");
  const { yaml, remaining } = parseFrontmatter(content);

  if (!yaml) {
    console.warn(`⚠️  Could not parse frontmatter for ${specName}`);
    return false;
  }

  // Add or update implementation field
  const implPath = path.join(AGENTS_DIR, implementationDir);
  if (!directoryExists(implPath)) {
    console.warn(
      `⚠️  Implementation directory does not exist: ${implementationDir}`,
    );
    return false;
  }

  yaml.implementation = implementationDir;

  // Update last_updated date
  yaml.last_updated = new Date().toISOString().split("T")[0];

  // Reconstruct and save
  const updated = reconstructMarkdown(yaml, remaining);
  fs.writeFileSync(specPath, updated, "utf8");

  console.log(
    `✅ Updated ${specName} with implementation: ${implementationDir}`,
  );
  return true;
}

/**
 * Main function
 */
function main() {
  console.log("Adding implementation references to agent specifications...\n");

  let successCount = 0;
  let skippedCount = 0;
  let failureCount = 0;

  for (const [specName, implDir] of Object.entries(IMPLEMENTATION_MAPPING)) {
    const specPath = path.join(AGENTS_DIR, `${specName}.agent.md`);

    if (!fs.existsSync(specPath)) {
      console.warn(`⚠️  Spec file not found: ${specName}.agent.md`);
      failureCount++;
      continue;
    }

    // Skip if no implementation directory defined
    if (implDir === null) {
      console.log(
        `⊘ Skipped ${specName} (internal/mode agent, no implementation directory)`,
      );
      skippedCount++;
      continue;
    }

    if (updateSpecFile(specName, specPath, implDir)) {
      successCount++;
    } else {
      failureCount++;
    }
  }

  console.log(`\n${"═".repeat(60)}`);
  console.log(
    `\nResults: ${successCount} updated, ${skippedCount} skipped, ${failureCount} failed\n`,
  );

  if (failureCount > 0) {
    process.exit(1);
  }
}

main();
